{
  "id": "p_002",
  "summary": "Diseño REST minimalista para gestionar tareas con recurso task, endpoints CRUD, códigos HTTP y formato de error estándar en JSON.",
  "approach": "Se modela task como recurso JSON con UUID generado por el servidor. Se exponen /tasks y /tasks/{id} con GET, POST, PATCH y DELETE. Las respuestas exitosas usan 200, 201 y 204; los errores usan 400, 404 y 422 con un objeto común code, message y details.",
  "tradeoffs": [
    "PATCH permite actualizaciones parciales simples, pero requiere validar campos presentes y mantener semántica explícita.",
    "Omitir autenticación, paginación y filtros reduce el alcance inicial, pero exigirá extensiones si se usa en producción.",
    "El modelo mínimo evita módulos fuera de alcance, aunque puede quedarse corto si se requieren más atributos de tarea."
  ],
  "evidence": [
    "Incluye GET /tasks, GET /tasks/{id}, POST /tasks, PATCH /tasks/{id} y DELETE /tasks/{id}.",
    "Define los códigos HTTP 200, 201, 204, 400, 404 y 422.",
    "Incluye ejemplos de request y response para crear, leer, actualizar y eliminar tareas, además del formato estándar de error."
  ],
  "artifacts": [],
  "http_status_codes": {
    "200": "OK para lecturas y actualizaciones exitosas.",
    "201": "Created para creación exitosa de una tarea.",
    "204": "No Content para eliminación exitosa.",
    "400": "Bad Request para JSON inválido o sintaxis incorrecta.",
    "404": "Not Found cuando la tarea no existe.",
    "422": "Unprocessable Entity para validaciones de negocio fallidas."
  },
  "resource": {
    "task": {
      "fields": {
        "id": {
          "type": "string",
          "format": "uuid",
          "constraints": ["server-generated", "read-only after creation"]
        },
        "title": {
          "type": "string",
          "constraints": ["required", "minLength=1", "maxLength=200"]
        },
        "description": {
          "type": "string",
          "constraints": ["optional", "nullable", "maxLength=2000"]
        },
        "status": {
          "type": "string",
          "enum": ["pending", "in_progress", "done"],
          "default": "pending"
        },
        "due_date": {
          "type": "string",
          "format": "date",
          "constraints": ["optional", "nullable", "ISO 8601 date"]
        },
        "created_at": {
          "type": "string",
          "format": "date-time",
          "constraints": ["server-generated", "read-only"]
        },
        "updated_at": {
          "type": "string",
          "format": "date-time",
          "constraints": ["server-generated", "updated on mutation"]
        }
      }
    }
  },
  "endpoints": [
    {
      "method": "GET",
      "path": "/tasks",
      "purpose": "Listar tareas.",
      "request_body": null,
      "responses": {
        "200": {
          "description": "Lista de tareas.",
          "body": {
            "type": "array",
            "items": {
              "$ref": "#/resource/task"
            }
          }
        }
      }
    },
    {
      "method": "GET",
      "path": "/tasks/{id}",
      "purpose": "Obtener una tarea por id.",
      "request_body": null,
      "responses": {
        "200": {
          "description": "Tarea encontrada.",
          "body": {
            "$ref": "#/resource/task"
          }
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        }
      }
    },
    {
      "method": "POST",
      "path": "/tasks",
      "purpose": "Crear una tarea.",
      "request_body": {
        "type": "object",
        "required": ["title"],
        "additionalProperties": false,
        "properties": {
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string",
            "nullable": true
          },
          "status": {
            "type": "string",
            "enum": ["pending", "in_progress", "done"]
          },
          "due_date": {
            "type": "string",
            "format": "date",
            "nullable": true
          }
        }
      },
      "responses": {
        "201": {
          "description": "Tarea creada.",
          "body": {
            "$ref": "#/resource/task"
          }
        },
        "400": {
          "description": "JSON inválido o sintaxis incorrecta.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        },
        "422": {
          "description": "Datos de negocio inválidos.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        }
      }
    },
    {
      "method": "PATCH",
      "path": "/tasks/{id}",
      "purpose": "Actualizar parcialmente una tarea.",
      "request_body": {
        "type": "object",
        "minProperties": 1,
        "additionalProperties": false,
        "properties": {
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string",
            "nullable": true
          },
          "status": {
            "type": "string",
            "enum": ["pending", "in_progress", "done"]
          },
          "due_date": {
            "type": "string",
            "format": "date",
            "nullable": true
          }
        }
      },
      "responses": {
        "200": {
          "description": "Tarea actualizada.",
          "body": {
            "$ref": "#/resource/task"
          }
        },
        "400": {
          "description": "JSON inválido o sintaxis incorrecta.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        },
        "422": {
          "description": "Datos de negocio inválidos.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        }
      }
    },
    {
      "method": "DELETE",
      "path": "/tasks/{id}",
      "purpose": "Eliminar una tarea.",
      "request_body": null,
      "responses": {
        "204": {
          "description": "Tarea eliminada sin contenido.",
          "body": null
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": {
            "$ref": "#/error_format/schema"
          }
        }
      }
    }
  ],
  "examples": {
    "create": {
      "request": {
        "method": "POST",
        "path": "/tasks",
        "body": {
          "title": "Preparar informe",
          "description": "Incluir métricas de uso",
          "status": "pending",
          "due_date": "2026-07-30"
        }
      },
      "response": {
        "status": 201,
        "body": {
          "id": "8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
          "title": "Preparar informe",
          "description": "Incluir métricas de uso",
          "status": "pending",
          "due_date": "2026-07-30",
          "created_at": "2026-06-17T09:00:00Z",
          "updated_at": "2026-06-17T09:00:00Z"
        }
      }
    },
    "list": {
      "request": {
        "method": "GET",
        "path": "/tasks",
        "body": null
      },
      "response": {
        "status": 200,
        "body": [
          {
            "id": "8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
            "title": "Preparar informe",
            "description": "Incluir métricas de uso",
            "status": "pending",
            "due_date": "2026-07-30",
            "created_at": "2026-06-17T09:00:00Z",
            "updated_at": "2026-06-17T09:00:00Z"
          }
        ]
      }
    },
    "get_by_id": {
      "request": {
        "method": "GET",
        "path": "/tasks/8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
        "body": null
      },
      "response": {
        "status": 200,
        "body": {
          "id": "8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
          "title": "Preparar informe",
          "description": "Incluir métricas de uso",
          "status": "pending",
          "due_date": "2026-07-30",
          "created_at": "2026-06-17T09:00:00Z",
          "updated_at": "2026-06-17T09:00:00Z"
        }
      }
    },
    "update": {
      "request": {
        "method": "PATCH",
        "path": "/tasks/8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
        "body": {
          "status": "in_progress"
        }
      },
      "response": {
        "status": 200,
        "body": {
          "id": "8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
          "title": "Preparar informe",
          "description": "Incluir métricas de uso",
          "status": "in_progress",
          "due_date": "2026-07-30",
          "created_at": "2026-06-17T09:00:00Z",
          "updated_at": "2026-06-17T10:15:00Z"
        }
      }
    },
    "delete": {
      "request": {
        "method": "DELETE",
        "path": "/tasks/8f0e6c2a-1d5b-4e2a-9f3b-2c6d7e9a1b2c",
        "body": null
      },
      "response": {
        "status": 204,
        "body": null
      }
    },
    "error": {
      "request": {
        "method": "POST",
        "path": "/tasks",
        "body": {
          "description": "Falta el título"
        }
      },
      "response": {
        "status": 422,
        "body": {
          "code": "validation_error",
          "message": "La solicitud contiene campos inválidos",
          "details": [
            {
              "field": "title",
              "issue": "title es obligatorio"
            }
          ]
        }
      }
    }
  },
  "error_format": {
    "content_type": "application/json",
    "schema": {
      "type": "object",
      "required": ["code", "message", "details"],
      "properties": {
        "code": {
          "type": "string",
          "description": "Código de error estable y legible por máquina."
        },
        "message": {
          "type": "string",
          "description": "Mensaje de error legible por humanos."
        },
        "details": {
          "type": "array",
          "description": "Errores de campo o reglas específicas.",
          "items": {
            "type": "object",
            "required": ["field", "issue"],
            "properties": {
              "field": {
                "type": "string"
              },
              "issue": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "example": {
      "code": "validation_error",
      "message": "La solicitud contiene campos inválidos",
      "details": [
        {
          "field": "title",
          "issue": "title es obligatorio"
        }
      ]
    }
  }
}
